_V50_BASE = types.ModuleType("_v50_frozen_v49")
_V50_BASE.__file__ = "<bundled-v49>"
_V50_BASE.__package__ = ""
sys.modules[_V50_BASE.__name__] = _V50_BASE
exec(compile(_V50_BASE_SOURCE, _V50_BASE.__file__, "exec"), _V50_BASE.__dict__)


def _v50_package(name):
    module = sys.modules.get(name)
    if module is None:
        module = types.ModuleType(name)
        module.__file__ = "<bundled-package:" + name + ">"
        module.__package__ = name
        module.__path__ = []
        sys.modules[name] = module
    return module


def _v50_load(name, source):
    parent, _, child = name.rpartition(".")
    if parent:
        _v50_package(parent)
    module = types.ModuleType(name)
    module.__file__ = "<bundled:" + name + ">"
    module.__package__ = parent
    sys.modules[name] = module
    exec(compile(source, module.__file__, "exec"), module.__dict__)
    if parent:
        setattr(sys.modules[parent], child, module)
    return module


