from v49.residual_controller import ResidualConfig as _V50ResidualConfig
from v50.hybrid import build_route_value_hybrid as _v50_build_alternative
from v50.hybrid import safe_action as _v50_safe_action
from v50.suffix_router import build_suffix_router as _v50_build_suffix

_V50_RESIDUAL_CONFIG = _V50ResidualConfig(**{'front_existing_sells': True, 'front_on_near': True, 'front_money_deficit': 4500.0, 'front_supply_threshold': 3.0, 'preempt_enabled': True, 'preempt_horizon': 3, 'preempt_maximum_batch': 12, 'near_scheduled_supply_weight': 1.0, 'adaptive_near_schedule_weight': False, 'preempt_money_deficit': 4000.0})
_V50_ALTERNATIVE = _v50_build_alternative(
    _V50_GIN_ROUTE,
    _V50_RESIDUAL_CONFIG,
)
_V50_POLICY = _v50_build_suffix(
    _V50_BASE.agent,
    _V50_ALTERNATIVE,
    lambda obs: True,
    decision_step=156,
)


def agent(obs, configuration=None):
    try:
        return _V50_POLICY(obs, configuration)
    except Exception:
        return _v50_safe_action(obs)


def _kaggle_submission_entrypoint(obs, configuration=None):
    return agent(obs, configuration)
